n = int(input())
import heapq
graph={'S':[('G',5),('A',1)],'A':[('G',1)],'G':[]}
if n==2:graph['S']=[('G',1)]
h={'S':0,'A':1,'G':0};front=[(0,0,'S')];best={'S':0}
while front:
 _,g,v=heapq.heappop(front)
 if g!=best[v]:continue
 if v=='G':print(g);break
 for w,c in graph[v]:
  ng=g+c
  if ng<best.get(w,float('inf')):best[w]=ng;heapq.heappush(front,(h[w],ng,w))

